public class Main {
    record Simpul(int v, Simpul kiri, Simpul kanan) {}
    static void telusur(Simpul s, List<Integer> in, List<Integer> pre, List<Integer> post) {
        if (s == null) return;
        pre.add(s.v());
        telusur(s.kiri(), in, pre, post);
        in.add(s.v());
        telusur(s.kanan(), in, pre, post);
        post.add(s.v());
    }

    public static void main(String[] args) throws Exception {
        Simpul a = new Simpul(8, new Simpul(3, new Simpul(1, null, null), new Simpul(6, null, null)), new Simpul(10, null, null));
        List<Integer> in = new ArrayList<>(), pre = new ArrayList<>(), post = new ArrayList<>();
        telusur(a, in, pre, post);
        System.out.println("in-order  : " + in + "\npre-order : " + pre + "\npost-order: " + post);
