static void transfer(Connection c, int dari, int ke, long n) throws SQLException {
    c.setAutoCommit(false);
    try (PreparedStatement kurang = c.prepareStatement("UPDATE rekening SET saldo = saldo - ? WHERE id = ?");
         PreparedStatement tambah = c.prepareStatement("UPDATE rekening SET saldo = saldo + ? WHERE id = ?")) {
        kurang.setLong(1, n); kurang.setInt(2, dari); kurang.executeUpdate();
        tambah.setLong(1, n); tambah.setInt(2, ke);   tambah.executeUpdate();
        c.commit();
    } catch (SQLException e) {
        c.rollback();
        throw e;
    } finally {
        c.setAutoCommit(true);
    }
}

