public class Main {
    static boolean luhn(String s) {
        String d = s.replace(" ", "");
        int total = 0;
        for (int i = 0; i < d.length(); i++) {
            int x = d.charAt(d.length() - 1 - i) - '0';
            if (i % 2 == 1) { x *= 2; if (x > 9) x -= 9; }
            total += x;
        }
        return total % 10 == 0;
    }

    public static void main(String[] args) throws Exception {
        for (String no : new String[]{"4539 1488 0343 6467", "4539 1488 0343 6468"}) System.out.println(no + " -> " + (luhn(no) ? "valid" : "tidak valid"));
    }
}

binary-search-membagi-dua-sampai-ketemu.code:
public class Main {
    public static void main(String[] args) {
        int[] harga = {5000, 8000, 12000, 15000, 20000, 27000, 35000};
        int cari = 20000;
        int kiri = 0, kanan = harga.length - 1, langkah = 0, posisi = -1;
        // WHILE: berhenti saat ketemu atau ruang pencarian habis
        while (kiri <= kanan) {
            langkah++;
            int tengah = (kiri + kanan) / 2;
            System.out.println("Langkah " + langkah + ": cek indeks " + tengah + " (" + harga[tengah] + ")");
            if (harga[tengah] == cari) {
                posisi = tengah;
                break;
            } else if (harga[tengah] < cari) {
                kiri = tengah + 1;
            } else {
                kanan = tengah - 1;
            }
        }
        System.out.println("Ketemu di indeks " + posisi + " setelah " + langkah + " langkah");
    }
}

